 const geoPosts=useMemo(()=>(m?.posts??[]).filter(p=>!geoLine||postLine(p,reportSales)===geoLine||geoLineSales.some(s=>s.post_id===p.post_id)).map(p=>({...p,orders:geoLineSales.filter(s=>s.post_id===p.post_id).length})).sort((a,b)=>b.orders-a.orders),[m,geoLine,reportSales,geoLineSales]);
 const geoSales=useMemo(()=>geoLineSales.filter(s=>!geoPost||s.post_id===geoPost),[geoLineSales,geoPost]);
 const geoCities=useMemo(()=>aggregate(geoSales,'ciudad_normalizada'),[geoSales]);
 const cityLeader=geoCities.find(c=>geoSales.some(s=>s.ciudad_normalizada===c.name&&s.departamento===c.department));
 const cities=useMemo(()=>aggregate(geoSales,geoLevel==='Ciudades'?'ciudad_normalizada':'departamento').sort((a,b)=>geoMetric==='Valor'?b.value-a.value:b.orders-a.orders),[geoSales,geoLevel,geoMetric]);
 useEffect(()=>{if(geoLine&&!geoLines.includes(geoLine)){setGeoLine('');setGeoPost('');setCityFilter('')}else if(geoPost&&!geoPosts.some(p=>p.post_id===geoPost)){setGeoPost('');setCityFilter('')}},[geoLine,geoLines,geoPost,geoPosts]);
 const role=snapshot?.profile.role??'visualizador',canEdit=role==='principal'||role==='analista';
