 async function api(url:string,method:string,body:unknown){const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error??'No pudimos completar la acción.');return d;}
 async function synchronize(){if(demo){setToast('Estás en demostración. La sincronización real se ejecuta desde una sesión autorizada.');return}setBusy(true);setSyncPhase('sync');try{const result=await api('/api/sync','POST',{});setSyncPhase('report');if(await refresh())setToast(result.message??'Ventas e informe actualizados desde Google Sheets.')}catch(e){setSyncPhase('report');await refresh();setToast((e as Error).message,true)}finally{setBusy(false);setSyncPhase(null)}}
 function changeMonth(value:string){setRange(monthRange(value));setPeriod('Mes');setSelected(null)}
 function changeDay(value:string){try{setRange(dayRange(value));setPeriod('Día');setSelected(null)}catch{setToast('Elige una fecha válida.',true)}}
 async function exportCSV(){if(!snapshot||!m||exporting)return;setExporting(true);try{let csv:string;if(demo){csv=view==='interacciones'?interactionsCSV(filterInteractions(interactionRows,reportSales,query,postLineFilter,sort),reportSales):view==='marcas'?brandsCSV(m.current,m.previous,selectedBrand):view==='ubicaciones'?toCSV(['Destino','Pedidos','Valor conocido COP','Ventas con total','Totales pendientes'],cities.filter(c=>!cityFilter||c.name===cityFilter).map(c=>[c.name,c.orders,c.pricedOrders?c.value:null,c.pricedOrders,c.pendingTotals])):toCSV(['Post ID','Creativo','Pedidos','Valor conocido COP','Ticket COP (solo totales conocidos)','Participación %','Ventas con total','Totales pendientes'],(view==='post-id'?visiblePosts:m.posts).map(p=>[p.post_id,p.nombre_creativo,p.orders,p.pricedOrders||!p.orders?p.value:null,p.ticket,p.share,p.pricedOrders,p.pendingTotals]));}else{const r=await fetch(`/api/export?from=${range.from}&to=${range.to}&view=${view}&q=${encodeURIComponent(query)}&filter=${encodeURIComponent(filter)}&sort=${sort}&level=${geoLevel}&post=${geoPost}&city=${encodeURIComponent(cityFilter)}&metric=${geoMetric}&brand=${encodeURIComponent(selectedBrand)}&marca=${encodeURIComponent(globalBrand)}&line=${encodeURIComponent(view==='ubicaciones'?geoLine:postLineFilter)}`);if(!r.ok){const d=await r.json();throw Error(d.error)}csv=await r.text()}const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`nomada-${demo?'DEMO-':''}${view}-${range.from}-${range.to}.csv`;a.click();URL.revokeObjectURL(url);setToast('Reporte exportado con los filtros del periodo.')}catch(e){setToast((e as Error).message,true)}finally{setExporting(false)}}
 async function savePost(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!snapshot)return;setFormError('');const f=new FormData(e.currentTarget);const post:CatalogPost={post_id:String(f.get('post_id')).trim().toUpperCase(),nombre_creativo:String(f.get('nombre_creativo')??'').trim()||String(f.get('post_id')).trim().toUpperCase(),campana:editing?.campana??'',producto:canonicalLine(f.get('producto')),marca:String(f.get('marca')??'').trim()||(manufacturer(String(f.get('producto')))==='Sin marca'?'':manufacturer(String(f.get('producto')))),plataforma:editing?.plataforma??'Otra',fecha_inicio:editing?.fecha_inicio||monthRange().to,activo:editing?.activo??true};if(!post.post_id||!post.producto){setFormError('Completa el Post ID y la línea.');return}if(!editing&&snapshot.catalog.some(p=>p.post_id===post.post_id)){setFormError('Ese Post ID ya está en el catálogo.');return}setBusy(true);try{if(demo){setSnapshot({...snapshot,catalog:editing?snapshot.catalog.map(p=>p.post_id===editing.post_id?post:p):[...snapshot.catalog,post]})}else{await api('/api/catalog',editing?'PATCH':'POST',post);await refresh()}setAdding(false);setEditing(null);setToast(demo?'Post ID guardado en esta demostración.':'Post ID guardado.')}catch(e){setFormError((e as Error).message)}finally{setBusy(false)}}
 async function togglePost(p:CatalogPost){if(!snapshot)return;try{if(demo)setSnapshot({...snapshot,catalog:snapshot.catalog.map(c=>c.post_id===p.post_id?{...c,activo:!c.activo}:c)});else{await api('/api/catalog','PATCH',{...p,activo:!p.activo});await refresh()}setToast(p.activo?'Post ID desactivado. Sus ventas se conservan.':'Post ID activado.')}catch(e){setToast((e as Error).message,true)}}
